DROP TABLE IF EXISTS `barang_spb`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `barang_spb` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `spb` bigint(20) unsigned NOT NULL,
  `barang_id` bigint(20) unsigned NOT NULL,
  `deskripsi` varchar(191) NOT NULL,
  `satuan` varchar(191) NOT NULL,
  `qty` int(11) NOT NULL,
  `keterangan` varchar(191) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `barang_spb_spb_foreign` (`spb`),
  KEY `barang_spb_barang_id_foreign` (`barang_id`),
  CONSTRAINT `barang_spb_barang_id_foreign` FOREIGN KEY (`barang_id`) REFERENCES `kategori_barang` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `barang_spb_spb_foreign` FOREIGN KEY (`spb`) REFERENCES `spb` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=936 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
