--
-- Table structure for table `penjualan`
--

DROP TABLE IF EXISTS `penjualan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `penjualan` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `invoice` bigint(20) unsigned NOT NULL,
  `nomor_invoice` varchar(191) NOT NULL,
  `tgl_penjualan` datetime NOT NULL,
  `customer` varchar(191) NOT NULL,
  `perusahaan` varchar(191) DEFAULT NULL,
  `no_telepon` varchar(191) NOT NULL,
  `admin` bigint(20) unsigned NOT NULL,
  `order_by` enum('Walk in','Tokopedia','Shopee','WhatsApp/Online','Sales') NOT NULL,
  `nama_sales` varchar(191) DEFAULT NULL,
  `tgl_selesai` date NOT NULL,
  `express` enum('Ya','Tidak') NOT NULL DEFAULT 'Tidak',
  `jumlah_item` int(11) NOT NULL,
  `dp` bigint(20) DEFAULT NULL,
  `jenis_pembayaran` enum('Cash Lunas','Cash Belum Lunas','Transfer DP','Transfer Lunas','DP','PO') NOT NULL,
  `no_rek` text DEFAULT NULL,
  `total_harga` bigint(20) NOT NULL,
  `status` enum('Lunas','Belum Lunas','Batal') NOT NULL,
  `alasan_batal` text DEFAULT NULL,
  `alasan_hapus` text DEFAULT NULL,
  `approval` enum('Lock','Unlock') NOT NULL DEFAULT 'Lock',
  `approved_at` timestamp NULL DEFAULT NULL,
  `potongan` bigint(20) DEFAULT NULL,
  `diskon` bigint(20) DEFAULT NULL,
  `ppn` bigint(20) DEFAULT NULL,
  `total_pembayaran` bigint(20) NOT NULL,
  `sisa_pembayaran` bigint(20) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `penjualan_invoice_foreign` (`invoice`),
  KEY `penjualan_admin_foreign` (`admin`),
  KEY `idx_penjualan_tgl` (`tgl_penjualan`),
  KEY `idx_penjualan_status` (`status`),
  KEY `idx_penjualan_no_inv` (`nomor_invoice`),
  KEY `idx_penjualan_approval` (`approval`),
  KEY `idx_penjualan_del_tgl` (`deleted_at`,`tgl_penjualan`),
  KEY `idx_penjualan_del_status` (`deleted_at`,`status`),
  KEY `idx_penjualan_jenis_bayar` (`jenis_pembayaran`),
  KEY `idx_penjualan_del_jenis_tgl` (`deleted_at`,`jenis_pembayaran`,`tgl_penjualan`),
  KEY `idx_penjualan_customer` (`customer`),
  KEY `idx_penjualan_perusahaan` (`perusahaan`),
  KEY `idx_penjualan_no_telepon` (`no_telepon`),
  KEY `idx_penjualan_del_invoice` (`deleted_at`,`invoice`),
  CONSTRAINT `penjualan_admin_foreign` FOREIGN KEY (`admin`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `penjualan_invoice_foreign` FOREIGN KEY (`invoice`) REFERENCES `invoice` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2627 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

