--
-- Table structure for table `penjualan_barang`
--

DROP TABLE IF EXISTS `penjualan_barang`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `penjualan_barang` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `barang_id` bigint(20) unsigned NOT NULL,
  `material_id` text DEFAULT NULL,
  `material_qty` text DEFAULT NULL,
  `penjualan_id` bigint(20) unsigned NOT NULL,
  `deskripsi_item` text NOT NULL,
  `qty` int(11) NOT NULL,
  `satuan` varchar(191) NOT NULL,
  `hargaBarang` bigint(20) NOT NULL,
  `jumlah_harga` bigint(20) NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  `material_panjang` text DEFAULT NULL,
  `material_lebar` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `penjualan_barang_barang_id_foreign` (`barang_id`),
  KEY `penjualan_barang_penjualan_id_foreign` (`penjualan_id`),
  CONSTRAINT `penjualan_barang_barang_id_foreign` FOREIGN KEY (`barang_id`) REFERENCES `barang` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `penjualan_barang_penjualan_id_foreign` FOREIGN KEY (`penjualan_id`) REFERENCES `penjualan` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5795 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

