DROP TABLE IF EXISTS `spj`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `spj` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `nomor_spj` varchar(191) NOT NULL,
  `perusahaan` varchar(191) NOT NULL,
  `nama_pemberi_tugas` varchar(191) NOT NULL,
  `nama_kurir` varchar(191) NOT NULL,
  `tanggal_tugas` date NOT NULL,
  `waktu_berangkat` time NOT NULL,
  `tujuan` varchar(191) NOT NULL,
  `biaya_bahan_bakar` decimal(12,2) DEFAULT NULL,
  `jarak_tempuh` double(8,2) DEFAULT NULL,
  `deskripsi_barang` text DEFAULT NULL,
  `keterangan_tambahan` text DEFAULT NULL,
  `deskripsi_tugas` text DEFAULT NULL,
  `jam_kembali` time DEFAULT NULL,
  `status` enum('Terbayar','Belum Bayar') NOT NULL DEFAULT 'Belum Bayar',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=46 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
