--
-- Table structure for table `spk`
--

DROP TABLE IF EXISTS `spk`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `spk` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `nomor_invoice` varchar(191) NOT NULL,
  `customer` varchar(191) NOT NULL,
  `jumlah` int(11) NOT NULL,
  `satuan` enum('Set','Pcs','Kotak','Blok','Lbr','Rim','Und') NOT NULL,
  `jenis_bahan` text DEFAULT NULL,
  `ketebalan` text DEFAULT NULL,
  `ukuran` text DEFAULT NULL,
  `lain` text DEFAULT NULL,
  `express` enum('Y','N') NOT NULL,
  `tgl_mulai` datetime NOT NULL,
  `target_selesai` datetime NOT NULL,
  `timeline` varchar(191) NOT NULL,
  `timeline_design` varchar(121) DEFAULT NULL,
  `timeline_produksi` varchar(121) DEFAULT NULL,
  `status_spk` enum('Selesai','Belum Selesai') NOT NULL,
  `status_kerja` enum('Selesai','Proses Design','Proses Produksi','Batal','Belum Diproses') NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `pekerjaan` text DEFAULT NULL,
  `gambar` varchar(191) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_spk_status_spk` (`status_spk`),
  KEY `idx_spk_status_kerja` (`status_kerja`),
  KEY `idx_spk_created_at` (`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=1995 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `spk`
--

LOCK TABLES `spk` WRITE;
/*!40000 ALTER TABLE `spk` DISABLE KEYS */;
